/* VS17/FS16-only adapter after the original V4 source identity check.
 * Generated bytes are compared to the physically tested probe in host tests.
 * These fingerprints detect accidental wrong input; the loader's original
 * code/control/source check and immutable V4 header pin remain authoritative.
 * Both results are malloc-owned. Do not also apply nvn_clip_vertex_source. */
#ifndef NVN_WAVE_FOLD_SHADER_H
#define NVN_WAVE_FOLD_SHADER_H
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
static inline unsigned nvn_wave_fold_source_is(const char *source,size_t bytes,uint64_t hash) {
    if(!source||strlen(source)!=bytes)return 0;
    uint64_t actual=UINT64_C(14695981039346656037);
    for(size_t i=0;i<bytes;i++)actual=(actual^(uint8_t)source[i])*UINT64_C(1099511628211);
    return actual==hash;
}
static inline char *nvn_wave_fold_replace(const char *source,const char *old,const char *replacement) {
    const char *at=strstr(source,old);size_t n=strlen(old),r=strlen(replacement),size=strlen(source);
    if(!at||strstr(at+n,old)||size>32768)return NULL;
    char *out=malloc(size-n+r+1);if(!out)return NULL;
    size_t prefix=(size_t)(at-source);memcpy(out,source,prefix);memcpy(out+prefix,replacement,r);
    memcpy(out+prefix+r,at+n,size-prefix-n+1);return out;
}
static inline char *nvn_wave_fold_vertex_source(const char *source) {
    if(!nvn_wave_fold_source_is(source,1270,UINT64_C(0x630115d67e6e7711)))return NULL;
    char *renamed=nvn_wave_fold_replace(source,"void main() {","void nvnOriginalVertexMain() {");if(!renamed)return NULL;
    static const char suffix[]=
        "\nuniform highp vec2 nvnClipControl;\n"
        "\nuniform highp vec2 mm_wave_viewport;\n"
        "uniform highp float mm_wave_target_height;\n"
        "varying mediump vec2 mm_wave_edge_rows;\n"
        "void main() {\n"
        "    nvnOriginalVertexMain();\n"
        "    gl_Position.y *= nvnClipControl.x;\n"
        "    if(nvnClipControl.y>0.5)gl_Position.z=2.0*gl_Position.z-gl_Position.w;\n"
        "    highp float row = (gl_Position.y/gl_Position.w*0.5+0.5)*mm_wave_viewport.y+mm_wave_viewport.x;\n"
        "    mm_wave_edge_rows = vec2(row,mm_wave_target_height-row)*(1.0/1024.0);\n"
        "}\n";
    size_t size=strlen(renamed);char *out=malloc(size+sizeof(suffix));
    if(out){memcpy(out,renamed,size);memcpy(out+size,suffix,sizeof(suffix));}
    free(renamed);return out;
}
static inline char *nvn_wave_fold_fragment_source(const char *source) {
    if(!nvn_wave_fold_source_is(source,1123,UINT64_C(0xa31dc9c505520997)))return NULL;
    char *varying=nvn_wave_fold_replace(source,"uniform mediump float mm_wave_inverse_rows;","varying mediump vec2 mm_wave_edge_rows;");
    if(!varying)return NULL;
    char *out=nvn_wave_fold_replace(varying,
        "texture2D(mm_wave_lookup, vec2(0.5, gl_FragCoord.y * mm_wave_inverse_rows)).r",
        "texture2D(mm_wave_lookup, mm_wave_edge_rows.x <= mm_wave_edge_rows.y ? vec2(0.25, mm_wave_edge_rows.x) : vec2(0.75, mm_wave_edge_rows.y)).r");
    free(varying);return out;
}
#endif
